import{_ as n,o as s,c as t,ag as i}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"플라톤과의 관계","slug":"플라톤과의-관계","link":"#플라톤과의-관계","children":[]},{"level":2,"title":"보편자","slug":"보편자","link":"#보편자","children":[]},{"level":2,"title":"보편자에 대한 지식","slug":"보편자에-대한-지식","link":"#보편자에-대한-지식","children":[{"level":3,"title":"상대주의(감각능력 긍정)와 주지주의(감각능력 부정)의 극복","slug":"상대주의-감각능력-긍정-와-주지주의-감각능력-부정-의-극복","link":"#상대주의-감각능력-긍정-와-주지주의-감각능력-부정-의-극복","children":[]},{"level":3,"title":"질료와 형상","slug":"질료와-형상","link":"#질료와-형상","children":[]}]},{"level":2,"title":"인식의 과정 (감각 → 지성)","slug":"인식의-과정-감각-→-지성","link":"#인식의-과정-감각-→-지성","children":[{"level":3,"title":"연역과 귀납","slug":"연역과-귀납","link":"#연역과-귀납","children":[]}]}],"relativePath":"philosophy/Epistemology/02. 아리스토텔레스.md","filePath":"philosophy/Epistemology/02. 아리스토텔레스.md"}'),a={name:"philosophy/Epistemology/02. 아리스토텔레스.md"};function r(o,l,e,p,g,h){return s(),t("div",null,[...l[0]||(l[0]=[i(`<p>마케도니아 출신, 플라톤의 제자, 알렉산더 대왕의 스승, 리케이온 설립. 논리학·실천철학·이론철학 등 다양한 방면의 철학을 다룸.</p><h2 id="플라톤과의-관계" tabindex="-1">플라톤과의 관계 <a class="header-anchor" href="#플라톤과의-관계" aria-label="Permalink to &quot;플라톤과의 관계&quot;">​</a></h2><p><strong>공통점</strong></p><ol><li>진정한 지식의 대상은 보편자</li><li>감각만으로는 보편자에 대한 지식을 얻을 수 없음</li></ol><p><strong>차이점</strong></p><ol><li><strong>보편자의 존재론적 지위·존재방식</strong><ul><li>플라톤: 이데아로 존재 (다수 위의 하나 논증)</li><li>아리스토텔레스: 개별자 내에 존재원리로서 존재 (제3인간 논증으로 플라톤 비판) <ul><li><strong>제3인간 논증</strong>: 다수의 인간(h1, h2, ...)을 인간이게 하는 형상 H1이 있다면(다수 위의 하나), 그 다수의 인간 + 형상 H1을 다시 인간이게 하는 형상 H2가 필요해지고, 이 과정이 무한히 반복됨(무한퇴행)</li></ul></li></ul></li><li>보편자의 인식 방식</li></ol><h2 id="보편자" tabindex="-1">보편자 <a class="header-anchor" href="#보편자" aria-label="Permalink to &quot;보편자&quot;">​</a></h2><ul><li>개별자와 별개로 독립적으로 존재하지 않음</li><li>개별자에 일방적으로 의존하지도 않음 — <strong>상호 의존적 관계</strong></li></ul><h2 id="보편자에-대한-지식" tabindex="-1">보편자에 대한 지식 <a class="header-anchor" href="#보편자에-대한-지식" aria-label="Permalink to &quot;보편자에 대한 지식&quot;">​</a></h2><p>두 가지 입장의 문제점</p><ol><li><strong>선천적 지식(상기)</strong>: 선천적 지식(존재에 대한 의식을 포함)임에도 뒤늦게 알게 된다는 것은 말이 안 됨</li><li><strong>선천적 지식 부정</strong>: 아무런 전제 없이 보편자에 대한 지식을 얻을 수는 없음</li></ol><p><strong>감각능력에서 시작된 인식능력</strong>: 어떤 개별자에 대한 반복 경험이 일정한 규칙의 형태로 나타남 = 보편적인 것</p><h3 id="상대주의-감각능력-긍정-와-주지주의-감각능력-부정-의-극복" tabindex="-1">상대주의(감각능력 긍정)와 주지주의(감각능력 부정)의 극복 <a class="header-anchor" href="#상대주의-감각능력-긍정-와-주지주의-감각능력-부정-의-극복" aria-label="Permalink to &quot;상대주의(감각능력 긍정)와 주지주의(감각능력 부정)의 극복&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 감각은 p라고 말한다.</span></span>
<span class="line"><span>2. 감각은 p가 아니라고 말한다.</span></span>
<span class="line"><span>3. 감각이 말하는 바는 참이다.</span></span>
<span class="line"><span>4. p인 동시에 p가 아닐 수는 없다.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><strong>프로타고라스(상대주의)</strong> = 4번 부정: 감각 사이의 충돌 상황에서 어느 한쪽 감각의 우위는 없다고 봄</li><li><strong>플라톤(주지주의)</strong> = 3번 부정: 지성에 의한 추론을 긍정</li></ul><p>아리스토텔레스는 <strong>고유감각</strong>을 통해 이를 해결 — 보는 것에 있어서는 시각이 우위인 것처럼, 감각들 사이에도 상대적 우위가 있음 (다만 절대적인 것은 아님).</p><h3 id="질료와-형상" tabindex="-1">질료와 형상 <a class="header-anchor" href="#질료와-형상" aria-label="Permalink to &quot;질료와 형상&quot;">​</a></h3><ul><li><strong>형상</strong>: 보편화 원리. 질료와 결합하여 존재하며, 개별자의 본질적 속성을 인식하게 함. 형상 = 본질</li><li><strong>질료</strong>: 물질적이며 시공간에 종속됨</li></ul><p><strong>본질</strong>: 개별자가 가진 모든 속성을 다 기술할 수는 없으나, 그중 필연적으로 가지는 속성.</p><h2 id="인식의-과정-감각-→-지성" tabindex="-1">인식의 과정 (감각 → 지성) <a class="header-anchor" href="#인식의-과정-감각-→-지성" aria-label="Permalink to &quot;인식의 과정 (감각 → 지성)&quot;">​</a></h2><ol><li><strong>감각</strong>: 개별자의 지각</li><li><strong>기억</strong>: 지각의 보존</li><li><strong>경험</strong>: 많은 기억의 축적과 패턴화</li><li><strong>지성</strong>: 본질적 속성을 파악 (추상, 직관)</li></ol><p><strong>감각만으로는</strong>: 우연적 성질과 본질적 성질을 구분할 수 없음 — 보편자에 대한 파악이 불가능한 열등한 지식.</p><p>지성은 빈 서판(백지)과 같아 그 자체만으로는 지식을 제공할 수 없음. 감각과 지성의 협력을 통해 보편자에 대한 지식으로 나아가야 함. 이 과정은 단순한 일반화가 아니라 <strong>추상과 직관</strong>의 과정을 거쳐야 함 (근대 경험론과 달리, 보편자에 대한 지식은 다시 감각으로 환원되지 않음).</p><p><strong>추상과 직관</strong></p><ul><li><strong>추상</strong>: 필요 없는 특징을 추출 — 개별자의 우연적 특징을 걷어내고 본질적인 속성만 남김 → 아리스토텔레스식 <strong>귀납</strong>(개별자 → 보편자). 단순한 일반화가 아니라, 개별 사례를 통해 보편적인 진술로 나아가는 과정</li><li><strong>직관</strong>: 추상의 결과물에 대한 즉각적인 파악 — 보편화된 지식과 개별적 지식을 매개시키는 과정</li></ul><p>개별적 지식 축적 → 추상을 통한 걷어냄 → 직관(매개 없이 직접 보는 것)</p><h3 id="연역과-귀납" tabindex="-1">연역과 귀납 <a class="header-anchor" href="#연역과-귀납" aria-label="Permalink to &quot;연역과 귀납&quot;">​</a></h3><ul><li><strong>연역</strong>: 예시로 제시된 명제가 모두 보편명제로 제시됨 — 전제가 참이면 결론이 참이므로 문제가 없음</li><li><strong>귀납</strong>: &quot;모든 인간, 모든 말...&quot; 처럼 특수한 어떤 것에 대한 인식(감각경험)으로부터 시작 — 귀납적인 내용이 포함되어야만 성립하며, 귀납을 통해 일반적 성질의 파악이 가능해짐 (단순한 일반화가 아니라, 모든 개별적 존재의 속성으로부터 본질적 속성을 파악하고 보편적 진술로 나아가는 과정)</li></ul><p>아리스토텔레스의 논리학은 제시된 명제가 참인지 확인하는 과정이 필요했던 반면, 현대 논리학은 전제가 참이라고 가정한 이후부터 시작함.</p><p><strong>4원인론</strong>: 어떤 속성이 본질적임을 인식하려면, 그 속성에 필연성을 부여하는 원인을 파악해야 함 — 형상인, 질료인, 작용인, 목적인.</p><ul><li>예: 책상은 작업하기 위해 만들어짐(<strong>목적인</strong>) → 그 목적에 맞게 설계됨(<strong>형상인</strong>) → 어떤 재료를 사용할지 정해짐(<strong>질료인</strong>) → 장인이 만들기 위해 힘을 가함(<strong>작용인</strong>)</li><li>형상은 목적에 부합하게 만들어짐 (상호 간 일부 대체 가능한 경우도 있음)</li><li>원인에 대한 인식은 지성을 통해 가능함</li></ul>`,31)])])}const c=n(a,[["render",r]]);export{d as __pageData,c as default};
